def correct_bracketing(brackets: str) -> bool:
    stack = []
    brackets_map = {"<": ">"}
    for char in brackets:
        if char in brackets_map:
            stack.append(char)
        elif char == brackets_map[stack[-1]]:
            stack.pop()
        else:
            return False
    return not stack
