import string

def rotate_string(s):
    """Helper function to rotate the given string.
    The rotation is defined as a rotation down the alphabet by two positions.
    """
    return s.translate(str.maketrans(string.ascii_lowercase, string.ascii_lowercase[2:] + string.ascii_lowercase[:2]))

def encrypt(s):
    """Encrypt the given string by rotating by two positions in the alphabet.
    """
    translated = ""
    for char in s:
        if char.isalpha():
            translated += rotate_string(char)
        else:
            translated += char
    return translated
