from collections import Counter

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.
    If no letters are repeated, return an empty dictionary.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Split the input string into a list of individual letters
    letters = test.split()

    # Use Counter to count occurrences of each letter
    letter_counts = Counter(letters)

    # Initialize variables to keep track of the maximum count and the corresponding letters
    max_count = 0
    matching_letters = set()

    # Loop through the counts dictionary to find letters with the maximum count
    for letter, count in letter_counts.items():
        if count > max_count:
            max_count = count
            matching_letters = {letter}
        elif count == max_count:
            matching_letters.add(letter)

    # Return the dictionary where the keys are the matching letters and the values are their respective counts
    return dict((letter, count) for letter, count in matching_letters.items())
