def valid_date(date):
    import re

    # Check if the input is a valid date format mm-dd-yyyy
    regex = re.compile(r'\b([0-9]{2})-([0-9]{2})-([0-9]{4})\b')
    if not (re.fullmatch(regex, date) or date in ["0-0-0", "0-0-00", "00-0-000"]):
        return False

    # Extract the day, month, year from the input date
    day, month, year = map(int, date.split('-'))

    # Check if the date meets the rules for each field
    month_days = [31, 28 + (isleap(year)), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    return day <= month_days[month-1] and (year % 4 == 0 and isleap(year) or month != 2 or (28 + (isleap(year))) == month_days[month-1])

def isleap(year):
    """A Python function to return true if a given year is a leap year"""
    if year % 4 != 0:
        return False
    elif year % 100 != 0:
        return True
    elif year % 400 != 0:
        return False
    else:
        return True
