from typing import List

def prod_signs(arr: List[int]) -> int or None:
    if not arr:
        return None

    sign_product = 1
    total = 0

    for num in arr:
        sign_product *= num
        if num > 0:
            total += sign_product
        elif num < 0:
            total -= sign_product
        else:
            sign_product = 1

    return total
