def tri(n):
    if n < 1:
        return []

    tri_res = [3, 2, 3]

    for i in range(3, n + 1):
        if i % 2 == 0:
            tri_res.append(1 + i // 2)
        else:
            tri_res.append(tri_res[i - 1] + tri_res[i - 2] + tri_res[i + 1])

